#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;
use File::Basename qw(dirname basename);
use Cwd qw(abs_path);

my $REPO = abs_path("/bench/repo");
my @CALLER_ROOTS = map { "$REPO/$_" } qw(server cmd web);
my $INTERNAL = "$REPO/internal";
my $MODULE = "github.com/usememos/memos";

# Strip comments and string literals (best-effort).
sub strip_go {
    my ($s) = @_;
    my $out = '';
    my $i = 0;
    my $n = length($s);
    while ($i < $n) {
        if (substr($s, $i, 2) eq '//') {
            my $j = index($s, "\n", $i);
            $i = ($j < 0) ? $n : $j;
        } elsif (substr($s, $i, 2) eq '/*') {
            my $j = index($s, '*/', $i + 2);
            $i = ($j < 0) ? $n : $j + 2;
        } elsif (substr($s, $i, 1) =~ /["`]/) {
            my $q = substr($s, $i, 1);
            my $j = $i + 1;
            while ($j < $n) {
                my $c = substr($s, $j, 1);
                if ($c eq '\\') { $j += 2; next; }
                if ($c eq $q) { $j++; last; }
                $j++;
            }
            $out .= (' ' x ($j - $i));
            $i = $j;
        } else {
            $out .= substr($s, $i, 1);
            $i++;
        }
    }
    return $out;
}

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or die "open $path: $!";
    local $/;
    my $c = <$fh>;
    close $fh;
    return $c;
}

sub import_path_for_dir {
    my ($dir) = @_;
    my $rel = $dir;
    $rel =~ s/^\Q$INTERNAL\E\/?//;
    my $path = "$MODULE/internal";
    $path .= "/$rel" if length $rel;
    return $path;
}

# --- Collect declarations in internal/ ---
my %decls;      # key "path|recv|name" => {file,line,name,recv,path}
my %decls_by_pkg; # import_path -> [keys]

find(sub {
    return unless /\.go$/;
    my $path = $File::Find::name;
    my $content = read_file($path);
    my ($pkg) = $content =~ /^\s*package\s+(\w+)/m;
    my $import_path = import_path_for_dir($File::Find::dir);
    my $rel = substr($path, length($REPO) + 1);

    while ($content =~ /^func\s+(?:\(\s*\w+\s+\*?(\w+)\s*\)\s+)?(\w+)\s*(?:\(|{)/mg) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $line = 1 + (substr($content, 0, pos($content) - length($&)) =~ tr/\n//);
        my $key = "$import_path|$recv|$name";
        $decls{$key} = {
            file => $rel, line => $line, name => $name, recv => $recv,
            import_path => $import_path, pkg => $pkg,
        };
        push @{ $decls_by_pkg{$import_path} }, $key;
    }
}, $INTERNAL);

# --- Parse imports in a caller file ---
sub parse_imports {
    my ($content) = @_;
    my %imports; # local -> full path
    if ($content =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            $line =~ s/^\s+|\s+$//g;
            next unless length $line;
            next if $line =~ /^_\s/ || $line =~ /^\.\s/;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $p = $1;
                (my $local = $p) =~ s/.*\///;
                $imports{$local} = $p;
            }
        }
    }
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $p = $1;
        (my $local = $p) =~ s/.*\///;
        $imports{$local} = $p;
    }
    return \%imports;
}

# Map import path -> local aliases (can be multiple for same path? rare)
sub aliases_for_path {
    my ($imports, $target) = @_;
    my @a;
    for my $local (keys %$imports) {
        push @a, $local if $imports->{$local} eq $target;
    }
    return @a;
}

# --- Count call sites ---
my %fanin;       # key -> count
my %sites;       # key -> { "file:line" => 1 }

for my $root (@CALLER_ROOTS) {
    next unless -d $root;
    find(sub {
        return unless /\.go$/;
        my $path = $File::Find::name;
        my $rel = substr($path, length($REPO) + 1);
        my $raw = read_file($path);
        my $content = strip_go($raw);
        my $imports = parse_imports($raw);

        # Remove func declarations from content to avoid counting them
        my $body = $content;
        $body =~ s/^func\s+(?:\([^)]*\)\s+)?\w+\s*(?:\([^)]*\))?\s*\{/func __DECL__ {/mg;

        # For each internal package imported, count calls
        for my $import_path (keys %decls_by_pkg) {
            my @aliases = aliases_for_path($imports, $import_path);
            next unless @aliases;

            for my $key (@{ $decls_by_pkg{$import_path} }) {
                my $d = $decls{$key};
                my $name = $d->{name};
                my $recv = $d->{recv};

                if (!$recv) {
                    # Package-level function: alias.Name(
                    for my $alias (@aliases) {
                        my $pat = qr/\b\Q$alias\E\.\Q$name\E\s*\(/;
                        while ($body =~ /$pat/g) {
                            my $pos = pos($body) - 1;
                            my $line = 1 + (substr($body, 0, $pos) =~ tr/\n//);
                            my $site = "$rel:$line";
                            next if $sites{$key}{$site}++;
                            $fanin{$key}++;
                        }
                    }
                } else {
                    # Method: harder - count .Name( where preceded by non-dot identifier
                    # Also package constructors may return type enabling method calls
                    # Pattern: something.Name( where something isn't a known package alias call chain start
                    # We'll count selector calls .Name( and try to exclude alias.Func declarations
                    my $pat = qr/(?<![.\w])\.\Q$name\E\s*\(/;
                    # Too broad for methods - skip generic method matching for now
                    # Instead match explicit type construction then method on same line is rare
                }
            }
        }

        # Also count unqualified calls to internal functions when caller is in same package - N/A for server/cmd

        # Method calls via variables: for declared methods, count .MethodName(
        # This catches r.Render(, renderer.Render(, etc.
        for my $key (keys %decls) {
            my $d = $decls{$key};
            next unless $d->{recv};
            my $name = $d->{name};
            my $import_path = $d->{import_path};
            # Only count if this file imports the package (heuristic for method use)
            my @aliases = aliases_for_path($imports, $import_path);
            next unless @aliases;

            my $pat = qr/(?<![.\w])\.\Q$name\E\s*\(/;
            while ($body =~ /$pat/g) {
                my $pos = pos($body) - 1;
                # Exclude package-qualified: alias.name already counted above for funcs
                # For methods, check we're not matching alias.Name(
                my $before = substr($body, 0, $pos);
                if ($before =~ /(\w+)\.\Q$name\E\s*\($/s) {
                    my $prefix = $1;
                    next if grep { $_ eq $prefix } @aliases;
                }
                my $line = 1 + (substr($body, 0, $pos) =~ tr/\n//);
                my $site = "$rel:$line";
                next if $sites{$key}{$site}++;
                $fanin{$key}++;
            }
        }
    }, $root);
}

# Rank results
my @ranked = sort { ($fanin{$b} // 0) <=> ($fanin{$a} // 0) || $a cmp $b } keys %fanin;

print "=== TOP 30 BY DISTINCT CALL SITE FAN-IN (server/cmd/web callers) ===\n";
for my $i (0..29) {
    last unless $i < @ranked;
    my $k = $ranked[$i];
    my $d = $decls{$k};
    my $cnt = $fanin{$k};
    my $sym = $d->{recv} ? "($d->{recv}).$d->{name}" : $d->{name};
    print sprintf("%3d  %4d  %s  %s:%d  [%s]\n",
        $i+1, $cnt, $sym, $d->{file}, $d->{line}, $d->{import_path});
}

print "\n=== TOTAL DECLARATIONS: ", scalar(keys %decls), " ===\n";
print "=== DECLARATIONS WITH >=1 CALL SITE: ", scalar(@ranked), " ===\n";

# Also show top by simple grep for package-level funcs (cross-check)
print "\n=== GREP CROSS-CHECK: top package-level exported funcs ===\n";

