#!/usr/bin/env perl
use strict;
use warnings;

my $REPO = "/bench/repo";
my @CALLER_ROOTS = map { "$REPO/$_" } qw(server cmd web);
my $INTERNAL = "$REPO/internal";
my $MODULE = "github.com/usememos/memos";

sub list_go_files {
    my ($dir) = @_;
    return () unless -d $dir;
    open my $fh, '-|', "find", $dir, '-name', '*.go', '-type', 'f' or die "find: $!";
    chomp(my @files = <$fh>);
    close $fh;
    return @files;
}

sub strip_go {
    my ($s) = @_;
    my $out = '';
    my $i = 0;
    my $n = length($s);
    while ($i < $n) {
        if (substr($s, $i, 2) eq '//') {
            my $j = index($s, "\n", $i);
            $i = ($j < 0) ? $n : $j;
        } elsif (substr($s, $i, 2) eq '/*') {
            my $j = index($s, '*/', $i + 2);
            $i = ($j < 0) ? $n : $j + 2;
        } elsif (substr($s, $i, 1) =~ /["`]/) {
            my $q = substr($s, $i, 1);
            my $j = $i + 1;
            while ($j < $n) {
                my $c = substr($s, $j, 1);
                if ($c eq '\\') { $j += 2; next; }
                if ($c eq $q) { $j++; last; }
                $j++;
            }
            $out .= (' ' x ($j - $i));
            $i = $j;
        } else {
            $out .= substr($s, $i, 1);
            $i++;
        }
    }
    return $out;
}

sub read_file {
    my ($path) = @_;
    open my $fh, '<', $path or die "open $path: $!";
    local $/;
    my $c = <$fh>;
    close $fh;
    return $c;
}

sub import_path_for_file {
    my ($path) = @_;
    my $dir = $path;
    $dir =~ s/\/[^\/]+$//;
    my $rel = $dir;
    $rel =~ s/^\Q$INTERNAL\E\/?//;
    my $import_path = "$MODULE/internal";
    $import_path .= "/$rel" if length $rel;
    return $import_path;
}

# --- Collect declarations in internal/ ---
my %decls;
my %decls_by_pkg;

for my $path (list_go_files($INTERNAL)) {
    my $content = read_file($path);
    my ($pkg) = $content =~ /^\s*package\s+(\w+)/m;
    my $import_path = import_path_for_file($path);
    my $rel = substr($path, length($REPO) + 1);

    while ($content =~ /^func\s+(?:\(\s*\w+\s+\*?(\w+)\s*\)\s+)?(\w+)\s*(?:\(|{)/mg) {
        my ($recv, $name) = ($1 // '', $2);
        next if $name eq 'init';
        my $line = 1 + (substr($content, 0, pos($content) - length($&)) =~ tr/\n//);
        my $key = "$import_path|$recv|$name";
        $decls{$key} = {
            file => $rel, line => $line, name => $name, recv => $recv,
            import_path => $import_path, pkg => $pkg,
        };
        push @{ $decls_by_pkg{$import_path} }, $key;
    }
}

sub parse_imports {
    my ($content) = @_;
    my %imports;
    if ($content =~ /import\s*\((.*?)\)/s) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            $line =~ s/^\s+|\s+$//g;
            next unless length $line;
            next if $line =~ /^_\s/ || $line =~ /^\.\s/;
            if ($line =~ /^(\w+)\s+"([^"]+)"/) {
                $imports{$1} = $2;
            } elsif ($line =~ /^"([^"]+)"/) {
                my $p = $1;
                (my $local = $p) =~ s/.*\///;
                $imports{$local} = $p;
            }
        }
    }
    while ($content =~ /import\s+"([^"]+)"/g) {
        my $p = $1;
        (my $local = $p) =~ s/.*\///;
        $imports{$local} = $p;
    }
    return \%imports;
}

sub aliases_for_path {
    my ($imports, $target) = @_;
    my @a;
    for my $local (keys %$imports) {
        push @a, $local if $imports->{$local} eq $target;
    }
    return @a;
}

my %fanin;
my %sites;

for my $root (@CALLER_ROOTS) {
    for my $path (list_go_files($root)) {
        my $rel = substr($path, length($REPO) + 1);
        my $raw = read_file($path);
        my $content = strip_go($raw);
        my $imports = parse_imports($raw);

        my $body = $content;
        $body =~ s/^func\s+(?:\([^)]*\)\s+)?\w+\s*(?:\([^)]*\))?\s*\{/func __DECL__ {/mg;

        for my $import_path (keys %decls_by_pkg) {
            my @aliases = aliases_for_path($imports, $import_path);
            next unless @aliases;

            for my $key (@{ $decls_by_pkg{$import_path} }) {
                my $d = $decls{$key};
                next if $d->{recv};
                my $name = $d->{name};
                for my $alias (@aliases) {
                    my $pat = qr/\b\Q$alias\E\.\Q$name\E\s*\(/;
                    while ($body =~ /$pat/g) {
                        my $pos = pos($body) - 1;
                        my $line = 1 + (substr($body, 0, $pos) =~ tr/\n//);
                        my $site = "$rel:$line";
                        next if $sites{$key}{$site}++;
                        $fanin{$key}++;
                    }
                }
            }
        }

        for my $key (keys %decls) {
            my $d = $decls{$key};
            next unless $d->{recv};
            my $name = $d->{name};
            my $import_path = $d->{import_path};
            my @aliases = aliases_for_path($imports, $import_path);
            next unless @aliases;

            my $pat = qr/(?<![.\w])\.\Q$name\E\s*\(/;
            while ($body =~ /$pat/g) {
                my $pos = pos($body) - 1;
                my $before = substr($body, 0, $pos);
                if ($before =~ /(\w+)\.\Q$name\E\s*\($/s) {
                    my $prefix = $1;
                    next if grep { $_ eq $prefix } @aliases;
                }
                my $line = 1 + (substr($body, 0, $pos) =~ tr/\n//);
                my $site = "$rel:$line";
                next if $sites{$key}{$site}++;
                $fanin{$key}++;
            }
        }
    }
}

my @ranked = sort { ($fanin{$b} // 0) <=> ($fanin{$a} // 0) || $a cmp $b } keys %fanin;

print "=== TOP 40 BY DISTINCT CALL SITE FAN-IN (server/cmd/web callers) ===\n";
for my $i (0..39) {
    last unless $i < @ranked;
    my $k = $ranked[$i];
    my $d = $decls{$k};
    my $cnt = $fanin{$k};
    my $sym = $d->{recv} ? "(*$d->{recv}).$d->{name}" : $d->{name};
    print sprintf("%3d  %4d  %-40s  %s:%d\n", $i+1, $cnt, $sym, $d->{file}, $d->{line});
}

print "\nTOTAL internal decls: ", scalar(keys %decls), "\n";
print "Decls with fan-in: ", scalar(@ranked), "\n";

